const SCALE = 50; // px per degree of latitude
const X_SCALE = SCALE * Math.cos((CENTER_LATITUDE * Math.PI) / 180);

const MAP_WIDTH = Math.round((VIEW.east - VIEW.west) * X_SCALE);
const MAP_HEIGHT = Math.round((VIEW.north - VIEW.south) * SCALE);

const project = ([lon, lat]) => [(lon - VIEW.west) * X_SCALE, (VIEW.north - lat) * SCALE];

const formatPoint = point => project(point).map(n => n.toFixed(1)).join(',');

/** Closed SVG path for one or more rings. */
const toPolygonPath = rings => rings.map(ring => `M${ring.map(formatPoint).join('L')}Z`).join('');

/** Open SVG path for a line. */
const toLinePath = points => `M${points.map(formatPoint).join('L')}`;
